/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumPairRemoval = function(nums) {
    let sorted = false;
    let operations = 0;

    while (!sorted) {
        sorted = true;

        let lowestPair = null;
        let lowestPairValue = Infinity;

        for (let i = 0; i < nums.length - 1; i++) {
            if (nums[i] > nums[i + 1]) {
                sorted = false;
            }

            const sum = nums[i] + nums[i + 1];
            if (sum < lowestPairValue) {
                lowestPair = [i, i + 1];
                lowestPairValue = sum;
            }
        }

        if (!sorted && lowestPair) {
            nums[lowestPair[0]] += nums[lowestPair[1]];
            nums.splice(lowestPair[1], 1);
            operations++;
        }
    }

    return operations;
};
